def findAnagrams(s, p):
    if len(p) > len(s):
        return []

    cnt_p = [0] * 26
    cnt_s = [0] * 26

    for ch in p:
        cnt_p[ord(ch) - 97] += 1

    res = []
    for i, ch in enumerate(s):
        cnt_s[ord(ch) - 97] += 1
        if i >= len(p):
            cnt_s[ord(s[i - len(p)]) - 97] -= 1
        if cnt_s == cnt_p:
            res.append(i - len(p) + 1)

    return res

