def subarraySum(nums, k):
    prefix = {0: 1}
    cur_sum = 0
    count = 0

    for num in nums:
        cur_sum += num
        if cur_sum - k in prefix:
            count += prefix[cur_sum - k]
        prefix[cur_sum] = prefix.get(cur_sum, 0) + 1

    return count

