def rotate(nums, k):
    n = len(nums)
    if n == 0:
        return nums
    k %= n
    if k == 0:
        return nums

    def reverse(l, r):
        while l < r:
            nums[l], nums[r] = nums[r], nums[l]
            l += 1
            r -= 1

    reverse(0, n - 1)
    reverse(0, k - 1)
    reverse(k, n - 1)
    return nums

